# Rust 實現 Merkle Proof

## 完整代碼

```rust
use sha2::{Digest, Sha256};

// ============================================================
// 類型定義
// ============================================================

/// 哈希值類型（32 字節）
type Hash = [u8; 32];

/// Merkle Proof 中每一步的方向
#[derive(Debug, Clone)]
pub enum ProofDirection {
    Left,   // 兄弟節點在左側
    Right,  // 兄弟節點在右側
}

/// Merkle Proof 中的一個節點
#[derive(Debug, Clone)]
pub struct ProofNode {
    pub hash: Hash,
    pub direction: ProofDirection,
}

/// Merkle Tree 結構
pub struct MerkleTree {
    /// 所有層的節點，layers[0] 是葉子層，layers[最後] 是根
    layers: Vec<Vec<Hash>>,
    /// 葉子節點數量
    leaf_count: usize,
}

// ============================================================
// 哈希工具函數
// ============================================================

fn hash_leaf(data: &[u8]) -> Hash {
    let mut hasher = Sha256::new();
    hasher.update(&[0x00]); // 葉子前綴，防止 second-preimage attack
    hasher.update(data);
    hasher.finalize().into()
}

fn hash_pair(left: &Hash, right: &Hash) -> Hash {
    let mut hasher = Sha256::new();
    hasher.update(&[0x01]); // 內部節點前綴
    hasher.update(left);
    hasher.update(right);
    hasher.finalize().into()
}

fn hash_to_hex(hash: &Hash) -> String {
    hash.iter().map(|b| format!("{:02x}", b)).collect()
}

// ============================================================
// MerkleTree 實現
// ============================================================

impl MerkleTree {
    /// 從數據切片構建 Merkle Tree
    pub fn build(data: &[&[u8]]) -> Option<Self> {
        if data.is_empty() {
            return None;
        }

        let leaf_count = data.len();

        // 第 0 層：葉子哈希
        let mut current_layer: Vec<Hash> = data.iter().map(|d| hash_leaf(d)).collect();

        let mut layers = vec![current_layer.clone()];

        // 逐層往上合并，直到只剩一個節點（根）
        while current_layer.len() > 1 {
            let mut next_layer = Vec::new();

            let mut i = 0;
            while i < current_layer.len() {
                if i + 1 < current_layer.len() {
                    // 有配對節點，正常合并
                    next_layer.push(hash_pair(&current_layer[i], &current_layer[i + 1]));
                } else {
                    // 奇數個節點，最後一個和自己配對（複製）
                    next_layer.push(hash_pair(&current_layer[i], &current_layer[i]));
                }
                i += 2;
            }

            layers.push(next_layer.clone());
            current_layer = next_layer;
        }

        Some(Self { layers, leaf_count })
    }

    /// 獲取根哈希
    pub fn root(&self) -> &Hash {
        self.layers.last().unwrap().first().unwrap()
    }

